    ('e51d2d85-f4de-51c9-b417-143c9f451ea6', 'af3ddf84-3a13-56ec-beca-cfd0589e44ff', (SELECT id FROM category WHERE slug = 'reparacao-fugas'), 'Fuga de água por baixo do lava-loiça', 'Notei uma poça pequena todas as manhãs debaixo do lava-loiça da cozinha. Pode ser a torneira ou o sifão — preciso de alguém que venha ver esta semana.', 'Rua das Amoreiras 45, 3º Dto', '1250-021', 'Lisboa', 'PT-LIS', 'PT', ST_SetSRID(ST_MakePoint(-9.1393, 38.7223), 4326)::geography, 'HIGH', 'Dias úteis depois das 18h, fins de semana todo o dia', 'IN_NEGOTIATION', now() - make_interval(hours => 29), now() - make_interval(hours => 30)),
    ('95100bf7-4255-5baa-979b-f032d86b41ca', 'af3ddf84-3a13-56ec-beca-cfd0589e44ff', (SELECT id FROM category WHERE slug = 'pintura-interiores'), 'Pintar T2 completo em Alvalade', 'Apartamento T2 (68 m²) precisa de pintura geral — sala, dois quartos, corredor e casa de banho. Cor branca, tinta já escolhida.', 'Av. Rio de Janeiro 12', '1700-330', 'Lisboa', 'PT-LIS', 'PT', ST_SetSRID(ST_MakePoint(-9.1393, 38.7223), 4326)::geography, 'NORMAL', 'Qualquer altura em outubro', 'PUBLISHED', now() - make_interval(hours => 7), now() - make_interval(hours => 8)),
    ('5a84f92e-9239-5735-a0ec-b33c99d798a3', 'fd56b08b-89e8-57f3-a42d-bdedea637cb0', (SELECT id FROM category WHERE slug = 'instalacao-ar-condicionado'), 'Instalar ar condicionado no quarto', 'Quarto de casal (18 m²) sem ar condicionado. Já tenho o aparelho comprado (Daikin 12000 BTU), preciso só da instalação.', 'Rua do Loureiro 8', '4050-115', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'NORMAL', 'Fins de semana', 'CONFIRMED', now() - make_interval(hours => 118), now() - make_interval(hours => 120)),
    ('f460f257-5a1e-512d-b47f-431dcea588da', 'fd56b08b-89e8-57f3-a42d-bdedea637cb0', (SELECT id FROM category WHERE slug = 'canalizacao'), 'Substituir torneira da banheira', 'A torneira da banheira não fecha bem e está a gastar água. Peço substituição por uma nova (posso comprar eu ou o prestador trazer).', 'Rua de Cedofeita 210', '4050-179', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'LOW', 'Sem pressa, qualquer dia', 'DRAFT', NULL, now() - make_interval(hours => 2)),
    ('aad8bab0-f717-523f-9fb1-790027314174', 'a17393e9-4a87-5718-8bfc-d5878a5f8917', (SELECT id FROM category WHERE slug = 'remodelacao-cozinhas'), 'Remodelar cozinha pequena (9 m²)', 'Cozinha antiga precisa de remodelação completa: móveis, canalização e eletricidade. Já tenho o projeto do arquiteto.', 'Rua Nova de São Mamede 3', '2710-562', 'Sintra', 'PT-SNT', 'PT', ST_SetSRID(ST_MakePoint(-9.3817, 38.8029), 4326)::geography, 'NORMAL', 'A partir de novembro', 'PUBLISHED', now() - make_interval(hours => 4), now() - make_interval(hours => 5)),
    ('1525af12-baeb-580e-b2a3-c4fcaa58c07a', 'a17393e9-4a87-5718-8bfc-d5878a5f8917', (SELECT id FROM category WHERE slug = 'jardinagem'), 'Cortar relva e aparar sebe do quintal', 'Quintal de moradia (200 m²) com relva alta e sebe desalinhada. Serviço pontual, não é contrato.', 'Rua das Camélias 22', '2765-193', 'Cascais', 'PT-CSC', 'PT', ST_SetSRID(ST_MakePoint(-9.4215, 38.6979), 4326)::geography, 'LOW', 'Qualquer dia útil de manhã', 'COMPLETED', now() - make_interval(hours => 398), now() - make_interval(hours => 400)),
    ('e2a286d2-a899-5134-a434-b55d707f49d7', '4bd03a3d-d77e-5587-9bd7-21de371f59a0', (SELECT id FROM category WHERE slug = 'desentupimentos'), 'Desentupir cano da cozinha urgente', 'A água não escoa de todo no lava-loiça, já tentei desentupidor manual e não resultou. Preciso de alguém hoje ou amanhã.', 'Rua de Santa Catarina 500', '4000-447', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'URGENT', 'Hoje ou amanhã, qualquer hora', 'PUBLISHED', now() - make_interval(hours => 3), now() - make_interval(hours => 3)),
    ('da9ea758-62cb-5728-babe-3b3a08da279b', '4bd03a3d-d77e-5587-9bd7-21de371f59a0', (SELECT id FROM category WHERE slug = 'instalacoes-electricas'), 'Instalar tomadas extra no escritório em casa', 'Preciso de mais 4 tomadas numa divisão que uso como escritório. Já tem quadro elétrico recente.', 'Rua Central 88', '4700-320', 'Braga', 'PT-BRG', 'PT', ST_SetSRID(ST_MakePoint(-8.4265, 41.5454), 4326)::geography, 'NORMAL', 'Tardes de semana', 'IN_PROGRESS', now() - make_interval(hours => 198), now() - make_interval(hours => 200)),
    ('e3c7258a-f17d-5cf5-9b02-eab39071548c', 'd570f2e8-068d-5d0a-9dd5-682343cf922f', (SELECT id FROM category WHERE slug = 'pintura-exteriores'), 'Pintar fachada de moradia (2 pisos)', 'Fachada com sinais de humidade e tinta a descascar. Precisa de tratamento antes de pintar.', 'Rua do Farol 15', '8005-400', 'Faro', 'PT-FAR', 'PT', ST_SetSRID(ST_MakePoint(-7.9304, 37.0194), 4326)::geography, 'NORMAL', 'Antes do inverno, urgência moderada', 'PUBLISHED', now() - make_interval(hours => 11), now() - make_interval(hours => 12)),
    ('3a7e0556-8998-58fc-a48e-06bb5e4e03e9', 'd570f2e8-068d-5d0a-9dd5-682343cf922f', (SELECT id FROM category WHERE slug = 'limpeza-domestica'), 'Limpeza profunda antes de mudança', 'Apartamento T3 vazio, preciso de limpeza profunda antes de entregar as chaves ao senhorio.', 'Rua da Prata 77', '1100-052', 'Lisboa', 'PT-LIS', 'PT', ST_SetSRID(ST_MakePoint(-9.1393, 38.7223), 4326)::geography, 'HIGH', 'Esta semana, qualquer dia', 'CANCELLED', now() - make_interval(hours => 89), now() - make_interval(hours => 90)),
    ('c23ece5c-f4de-5b44-972c-cfc0fb09e360', 'af3ddf84-3a13-56ec-beca-cfd0589e44ff', (SELECT id FROM category WHERE slug = 'mudancas-residenciais'), 'Mudança de T2 para T3 dentro da mesma zona', 'Mudança pequena, sem elevador no prédio de saída (2º andar), com elevador no de chegada.', 'Rua Actor Taborda 9', '1900-284', 'Lisboa', 'PT-LIS', 'PT', ST_SetSRID(ST_MakePoint(-9.1393, 38.7223), 4326)::geography, 'NORMAL', 'Fim de mês', 'PUBLISHED', now() - make_interval(hours => 19), now() - make_interval(hours => 20)),
    ('d54e1467-b00d-5276-b583-7969460d8cfc', 'fd56b08b-89e8-57f3-a42d-bdedea637cb0', (SELECT id FROM category WHERE slug = 'mobiliario-medida'), 'Roupeiro à medida para quarto de casal', 'Parede de 3,2 m disponível para roupeiro embutido até ao teto. Gostava de portas de correr.', 'Rua de Camões 60', '4000-142', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'LOW', 'Sem pressa', 'IN_NEGOTIATION', now() - make_interval(hours => 58), now() - make_interval(hours => 60)),
    ('6276fd54-41c3-537f-88f3-150416f9fe0c', 'a17393e9-4a87-5718-8bfc-d5878a5f8917', (SELECT id FROM category WHERE slug = 'portoes-automaticos'), 'Automatizar portão existente da garagem', 'Portão basculante manual, gostava de motorizar sem trocar o portão.', 'Rua da Igreja 4', '4400-025', 'Vila Nova de Gaia', 'PT-VNG', 'PT', ST_SetSRID(ST_MakePoint(-8.6118, 41.1239), 4326)::geography, 'NORMAL', 'Próximas duas semanas', 'PUBLISHED', now() - make_interval(hours => 14), now() - make_interval(hours => 15)),
    ('44180da3-5e57-551c-a1d5-217bee0cee27', '4bd03a3d-d77e-5587-9bd7-21de371f59a0', (SELECT id FROM category WHERE slug = 'instalacao-ar-condicionado'), 'Manutenção anual de dois ar condicionados', 'Dois splits instalados há 3 anos, nunca tiveram manutenção. Limpeza de filtros e verificação de gás.', 'Rua Fernão de Magalhães 300', '4300-190', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'LOW', 'Qualquer dia útil', 'COMPLETED', now() - make_interval(hours => 698), now() - make_interval(hours => 700)),
    ('e603ac58-84a5-5118-9271-c71194b44fb8', 'd570f2e8-068d-5d0a-9dd5-682343cf922f', (SELECT id FROM category WHERE slug = 'limpeza-escritorios'), 'Limpeza semanal de escritório pequeno', 'Escritório com 3 salas, cerca de 80 m². Procuro contrato de limpeza semanal, fora de horas.', 'Av. da Boavista 1200', '4100-114', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'NORMAL', 'Preferencialmente sextas à noite', 'PUBLISHED', now() - make_interval(hours => 39), now() - make_interval(hours => 40)),
    ('1258755d-55d5-5666-804e-75ca07e1d38f', 'af3ddf84-3a13-56ec-beca-cfd0589e44ff', (SELECT id FROM category WHERE slug = 'iluminacao'), 'Trocar iluminação da sala para LED', 'Sala com 3 pontos de luz antigos, quero mudar tudo para LED com regulação de intensidade.', 'Rua Alexandre Herculano 30', '1250-008', 'Lisboa', 'PT-LIS', 'PT', ST_SetSRID(ST_MakePoint(-9.1393, 38.7223), 4326)::geography, 'LOW', 'Sem pressa', 'DRAFT', NULL, now() - make_interval(hours => 1)),
    ('ad846fc7-c362-58ab-ab23-860f4f6e790d', 'fd56b08b-89e8-57f3-a42d-bdedea637cb0', (SELECT id FROM category WHERE slug = 'limpeza-pos-obra'), 'Limpeza pós-obra em apartamento remodelado', 'Acabou de terminar obra de remodelação, ficou muito pó e resíduos de tinta. Preciso de limpeza pesada antes de mudar mobília.', 'Rua do Almada 150', '4050-035', 'Porto', 'PT-PRT', 'PT', ST_SetSRID(ST_MakePoint(-8.6291, 41.1579), 4326)::geography, 'HIGH', 'Esta semana', 'PUBLISHED', now() - make_interval(hours => 5), now() - make_interval(hours => 6)),
    ('fc56a4b0-33d0-53e5-a138-6c905b170e0a', 'a17393e9-4a87-5718-8bfc-d5878a5f8917', (SELECT id FROM category WHERE slug = 'remodelacao-banheiros'), 'Impermeabilizar e remodelar casa de banho pequena', 'Casa de banho de serviço (3 m²) com infiltração para o quarto ao lado. Precisa de obra completa.', 'Rua Direita 18', '2710-501', 'Sintra', 'PT-SNT', 'PT', ST_SetSRID(ST_MakePoint(-9.3817, 38.8029), 4326)::geography, 'HIGH', 'O quanto antes', 'IN_PROGRESS', now() - make_interval(hours => 166), now() - make_interval(hours => 168))
